import json
import os
from http.server import HTTPServer, SimpleHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

from .meridian import MeridianClient
from .store import Store


def parse_pagination_params(query_string: str) -> tuple[int, int] | None:
    params = parse_qs(query_string)
    try:
        limit = int(params.get("limit", [50])[0])
        offset = int(params.get("offset", [0])[0])
        if limit < 0 or offset < 0:
            return None
        return (limit, offset)
    except (ValueError, IndexError):
        return None


def handle_health(store: Store) -> dict:
    return {
        "status": "ok",
        "payment_count": store.count(),
        "last_sync": store.last_sync(),
    }


def handle_payments(store: Store, limit: int, offset: int) -> dict:
    payments = store.all_payments()
    total = len(payments)
    page = payments[offset : offset + limit]
    return {
        "total": total,
        "limit": limit,
        "offset": offset,
        "payments": page,
    }


def handle_summary(store: Store) -> dict:
    payments = store.all_payments()
    if not payments:
        return {
            "count": 0,
            "total_minor": 0,
            "currency": None,
            "oldest": None,
            "newest": None,
        }

    total_minor = sum(p["amount_minor"] for p in payments)
    currency = payments[0]["currency"]
    oldest = min(p["created_at"] for p in payments)
    newest = max(p["created_at"] for p in payments)

    return {
        "count": len(payments),
        "total_minor": total_minor,
        "currency": currency,
        "oldest": oldest,
        "newest": newest,
    }


def handle_sync(client: MeridianClient, store: Store) -> dict:
    payments = client.fetch_all_payments()
    inserted = store.upsert_many(payments)
    total = store.count()
    return {
        "fetched": len(payments),
        "inserted": inserted,
        "total": total,
    }


class VendorSyncHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, store=None, client=None, **kwargs):
        self.store = store
        self.client = client
        super().__init__(*args, **kwargs)

    def log_message(self, format, *args):
        # Suppress default logging for cleaner output
        pass

    def _send_json(self, data: dict, status: int = 200) -> None:
        body = json.dumps(data).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, status: int, message: str) -> None:
        self._send_json({"error": message}, status)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        query = parsed.query

        if path == "/health":
            self._send_json(handle_health(self.store))
            return

        if path == "/payments":
            pagination = parse_pagination_params(query)
            if pagination is None:
                self._send_error(400, "Invalid limit or offset parameters")
                return
            limit, offset = pagination
            self._send_json(handle_payments(self.store, limit, offset))
            return

        if path == "/summary":
            self._send_json(handle_summary(self.store))
            return

        # Serve static files from web/ directory
        web_dir = os.path.join(os.path.dirname(__file__), "web")
        filepath = os.path.normpath(os.path.join(web_dir, parsed.path.lstrip("/")))
        if not filepath.startswith(web_dir):
            self._send_error(403, "Forbidden")
            return

        if os.path.isfile(filepath):
            try:
                with open(filepath, "rb") as f:
                    content = f.read()
                ext = os.path.splitext(filepath)[1]
                ct_map = {
                    ".html": "text/html",
                    ".css": "text/css",
                    ".js": "application/javascript",
                    ".json": "application/json",
                    ".png": "image/png",
                    ".svg": "image/svg+xml",
                }
                self.send_response(200)
                self.send_header("Content-Type", ct_map.get(ext, "application/octet-stream"))
                self.send_header("Content-Length", str(len(content)))
                self.end_headers()
                self.wfile.write(content)
            except OSError:
                self._send_error(404, "Not found")
        else:
            # Serve index.html for SPA routing
            index_path = os.path.join(web_dir, "index.html")
            if os.path.isfile(index_path):
                with open(index_path, "rb") as f:
                    content = f.read()
                self.send_response(200)
                self.send_header("Content-Type", "text/html")
                self.send_header("Content-Length", str(len(content)))
                self.end_headers()
                self.wfile.write(content)
            else:
                self._send_error(404, "Not found")

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"

        if path == "/sync":
            try:
                result = handle_sync(self.client, self.store)
                self._send_json(result)
            except Exception as e:
                self._send_error(500, str(e))
            return

        self._send_error(404, "Not found")


def serve(port: int, store: Store, client: MeridianClient) -> None:
    server_address = ("127.0.0.1", port)

    def handler(*args, **kwargs):
        return VendorSyncHandler(*args, store=store, client=client, **kwargs)

    with HTTPServer(server_address, handler) as httpd:
        httpd.serve_forever()
